# Exact check of the multiplicative reduction of Chan-Pak (lane architecture, S94).
# Claim R: the multiplicative monoid generated by G = {odd primes p != 7} + {49, 63, 343} + {7p : p prime, p != 3, 7}
# is exactly {odd N >= 1} minus {7, 21}; and without 343 it misses exactly the numbers 343 * 3^e? (we list the misses).
import sys
LIM = 2_000_000
sieve = bytearray([1]) * (LIM + 1); sieve[0] = sieve[1] = 0
for i in range(2, int(LIM ** 0.5) + 1):
    if sieve[i]:
        sieve[i * i::i] = bytearray(len(sieve[i * i::i]))
primes = [i for i in range(3, LIM + 1) if sieve[i]]
def closure(gens):
    ok = bytearray(LIM + 1); ok[1] = 1
    gens = sorted(set(g for g in gens if g <= LIM))
    # ok[n] = 1 iff n is a product of generators: n = g * m with ok[m]
    for n in range(3, LIM + 1, 2):
        pass
    # dynamic programming by increasing n: n in closure iff exists generator g | n with n/g in closure
    isgen = bytearray(LIM + 1)
    for g in gens: isgen[g] = 1
    # for each n, test divisors that are generators: do it by sieving from generators
    reach = bytearray(LIM + 1); reach[1] = 1
    for n in range(1, LIM + 1, 2):
        if not reach[n]: continue
        for g in gens:
            m = n * g
            if m > LIM: break
            reach[m] = 1
    return reach
G = [p for p in primes if p != 7] + [49, 63, 343] + [7 * p for p in primes if p not in (3, 7) and 7 * p <= LIM]
r = closure(G)
miss = [n for n in range(1, LIM + 1, 2) if not r[n]]
print("with 343: odd misses up to", LIM, "=", miss)
G2 = [g for g in G if g != 343]
r2 = closure(G2)
miss2 = [n for n in range(1, LIM + 1, 2) if not r2[n]]
print("without 343: number of odd misses =", len(miss2), "first:", miss2[:12])
# structure of the misses without 343: predicted {7, 21} + {7^a : a odd >= 3} + {3 * 7^a : a odd >= 3}
pred = {7, 21}
a = 3
while 7 ** a <= LIM:
    pred.add(7 ** a)
    if 3 * 7 ** a <= LIM: pred.add(3 * 7 ** a)
    a += 2
print("prediction for the misses without 343 holds:", set(miss2) == pred)
print("CHECK", "PASS" if miss == [7, 21] and set(miss2) == pred else "FAIL")
